{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE (Sum of Squared Error), also known as scatter, is a measure of clustering quality calculated as the total sum of the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2",
      "E7"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used as an objective function to evaluate clustering quality, where a lower SSE indicates that the centroids are a better representation of the points in their cluster.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

